// The Google Sheets node emits one item per row plus a row_number field.
// Keep every row whose Status column is still empty, check the columns the
// video needs, and cap the batch at maxPerRun. A row with a problem is skipped
// with a named reason instead of sinking the whole batch.
const cfg = $('Config').first().json;
const all = $input.all().map((i) => i.json);
const txt = (v) => String(v == null ? '' : v).trim();
const isEmpty = (v) => txt(v) === '';
const LOGO_URL_RE = /^https:\/\/[^\s'"<>]+$/i;

const rows = [];
const skipped = [];
for (const r of all) {
  if (!isEmpty(r.Status)) continue; // already recorded (or parked by hand)
  const problems = [];
  if (!txt(r.FirstName)) problems.push('FirstName is empty');
  if (!txt(r.Company)) problems.push('Company is empty');
  const logo = txt(r.LogoUrl);
  if (logo && !LOGO_URL_RE.test(logo)) {
    problems.push('LogoUrl is not a plain https URL — clear the cell to use a monogram instead');
  }
  if (problems.length) {
    skipped.push({ rowNumber: r.row_number, lead: txt(r.FirstName) || '(no name)', problems });
    continue;
  }
  rows.push({
    rowNumber: r.row_number,
    firstName: txt(r.FirstName),
    company: txt(r.Company),
    website: txt(r.Website),
    logoUrl: logo,
    role: txt(r.Role),
    // "Check lead logos" HEADs this URL once per lead. A lead with no logo is
    // ALREADY decided (the builder short-circuits on the empty LogoUrl and
    // never looks at the probe) — the API root is here only because the HTTP
    // node still needs some valid URL to keep the item alignment 1:1.
    logoProbeUrl: logo || txt(cfg.apiUrl) || 'https://api.zvid.io',
  });
}

const max = Math.max(1, Number(cfg.maxPerRun || 10));
const leftForNextRun = Math.max(0, rows.length - max);
const kept = rows.slice(0, max);

if (!kept.length) {
  return [{ json: { found: false, checked: all.length, skipped } }];
}

return kept.map((r) => ({
  json: { ...r, found: true, checked: all.length, leftForNextRun, skipped },
}));

// Every row already has a Status, so there is nobody to record for today.
// That is a normal, successful outcome — not an error.
const picked = $('Pick batch').first().json;
const skipped = picked.skipped || [];
return [{
  json: {
    rendered: false,
    reason: skipped.length
      ? 'No usable lead rows with an empty Status. ' + skipped.length + ' row(s) were skipped — see skipped below.'
      : 'No lead rows with an empty Status column. Add leads, or clear Status on the ones you want re-recorded.',
    rowsChecked: picked.checked,
    skipped,
  },
}];

// === buildBulkRequest — identical to the frame-reviewed standalone builder ===
// ONE templated Zvid project (every brand/Config value baked in as a literal,
// every per-lead value as a {{placeholder}}) plus one { variables, name } item
// per lead — exactly the body POST /api/render/bulk/api-key expects. The bulk
// endpoint resolves the placeholders per item server-side, so the whole lead
// list renders from a single request.

const CANVAS_W = 1920;
const CANVAS_H = 1080;

// Average glyph width as a fraction of the font size, measured off real
// renders of these two families and rounded UP: every wrap estimate below has
// to over-predict, never under-predict (a block that grows a line it was not
// given room for is the one way this layout can break).
const SERIF_EM = 0.56; // Fraunces-class display serif

/** A logo URL we are willing to put inside an <img src='…'> attribute. */
const LOGO_URL_RE = /^https:\/\/[^\s'"<>]+$/i;

/**
 * &<>"' → entities. Sheet data is untrusted: it lands inside html/svg, and
 * every attribute in this design is single-quoted, so the apostrophe has to go
 * too — LOGO_URL_RE already rejects it in URLs, but nothing should depend on
 * that being the only line of defence.
 */
function esc(s) {
  return String(s == null ? '' : s).replace(
    /[&<>"']/g,
    (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]
  );
}

/** Collapse whitespace, trim. */
function clean(v) {
  return String(v == null ? '' : v)
    .replace(/\s+/g, ' ')
    .trim();
}

/** Hard cap with an ellipsis, on a word boundary when there is one nearby. */
function cap(s, max) {
  const t = clean(s);
  if (t.length <= max) return t;
  const cut = t.slice(0, max - 1);
  const space = cut.lastIndexOf(' ');
  return (space > max * 0.6 ? cut.slice(0, space) : cut) + '…';
}

/** #RRGGBB (or #RGB) → rgba() string. Falls back to the hex on bad input. */
function rgba(hex, a) {
  const h = String(hex || '').replace('#', '');
  const full =
    h.length === 3
      ? h
          .split('')
          .map((c) => c + c)
          .join('')
      : h;
  const n = parseInt(full, 16);
  if (full.length !== 6 || Number.isNaN(n)) return hex;
  return (
    'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')'
  );
}

/** Greedy word-wrap estimate (deliberately pessimistic — see SERIF_EM). */
function wrapLines(text, fontPx, boxPx, avgEm) {
  const perLine = Math.max(6, Math.floor(boxPx / (fontPx * avgEm)));
  let lines = 1;
  let used = 0;
  for (const w of String(text).split(' ')) {
    const need = used === 0 ? w.length : used + 1 + w.length;
    if (need <= perLine) {
      used = need;
      continue;
    }
    lines += 1;
    used = Math.min(w.length, perLine);
  }
  return lines;
}

/** Largest size from `ladder` whose estimate fits in `maxLines`. */
function fitSize(text, ladder, boxPx, avgEm, maxLines) {
  for (const size of ladder) {
    if (wrapLines(text, size, boxPx, avgEm) <= maxLines) return size;
  }
  return ladder[ladder.length - 1];
}

/**
 * "https://cal.com/rita/15min" → "cal.com/rita/15min". Display only.
 * A booking link longer than the pill can hold falls back to the bare HOST:
 * "cal.com/ekaterina-vasilyevna-popova/fifte…" is not a link anybody can
 * retype, and the pill is the only call to action in the video.
 */
function prettyLink(url) {
  const raw = clean(url)
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/+$/, '');
  if (raw.length <= 42) return raw;
  return cap(raw.split('/')[0], 42);
}

/** Host only: "https://northwind.example/about" → "northwind.example". */
function domainOf(url) {
  const m = /^(?:https?:\/\/)?(?:www\.)?([^/?#\s]+)/i.exec(clean(url));
  return m ? cap(m[1].toLowerCase(), 30) : '';
}

/** Project/item `name`: letters, digits, spaces, _ and - only. */
function slugify(s, fallback) {
  const out = String(s == null ? '' : s)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48);
  return out || fallback;
}

// Monogram tints for leads with no usable logo. Every pair is a pale field
// with a deep letter: the letter's colour is what the API's contrast lint
// reads (style.color), and each one clears 4.5:1 against the paper backdrop.
const MONOGRAMS = [
  { bg: '#DCE6F2', ink: '#1B3B5A' },
  { bg: '#E9E2D3', ink: '#7A5620' },
  { bg: '#DBE9E1', ink: '#1F5B47' },
  { bg: '#EFE0E4', ink: '#7A2E45' },
  { bg: '#E1E2EF', ink: '#3A3A6B' },
];

/**
 * "a" or "an" for a job title. Vowel-initial words take "an"; an initialism
 * takes it from how the LETTER is said ("an SDR", "a VP"), which is why the
 * all-caps branch tests a different set.
 */
function article(word) {
  const w = clean(word).split(' ')[0] || '';
  if (/^[A-Z]{2,}/.test(w)) return /^[AEFHILMNORSX]/.test(w) ? 'an' : 'a';
  return /^[aeiou]/i.test(w) ? 'an' : 'a';
}

/** Stable per-company tint — the same company always gets the same colour. */
function monogramFor(company) {
  const key = clean(company).toUpperCase();
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) % 100000;
  const letter = (key.match(/[A-Z0-9]/) || ['•'])[0];
  const tint = MONOGRAMS[h % MONOGRAMS.length];
  return { letter, bg: tint.bg, ink: tint.ink };
}

/**
 * Decide whether a lead's LogoUrl can be drawn.
 * `probe` is the HEAD response from "Check lead logos" ({statusCode, headers}).
 * Only DEFINITIVE evidence downgrades a lead to the monogram: a 4xx/5xx, a
 * non-image content-type, or a file over maxLogoBytes. A 405/501 (HEAD not
 * allowed) or a missing probe keeps the logo — plenty of CDNs refuse HEAD.
 */
function logoVerdict(logoUrl, probe, maxLogoBytes) {
  const url = clean(logoUrl);
  if (!LOGO_URL_RE.test(url)) {
    return { ok: false, reason: url ? 'LogoUrl is not a plain https URL' : 'no LogoUrl' };
  }
  if (!probe || typeof probe !== 'object') return { ok: true, reason: 'not probed' };
  const status = Number(probe.statusCode);
  if (status === 405 || status === 501) return { ok: true, reason: 'HEAD not allowed' };
  if (Number.isFinite(status) && status >= 400) {
    return { ok: false, reason: 'logo URL returned HTTP ' + status };
  }
  const headers = probe.headers || {};
  const type = String(headers['content-type'] || headers['Content-Type'] || '').toLowerCase();
  if (type && !/^image\//.test(type)) {
    return { ok: false, reason: 'logo URL is ' + type.split(';')[0] + ', not an image' };
  }
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  if (bytes && bytes > Number(maxLogoBytes || 2097152)) {
    return { ok: false, reason: 'logo is ' + Math.round(bytes / 1024) + ' KB, over the limit' };
  }
  return { ok: true, reason: 'ok' };
}

/**
 * The shared template. Everything the SENDER controls is baked in as a
 * literal; everything the LEAD controls rides on a {{placeholder}} that the
 * bulk endpoint resolves per item.
 *
 * Layout note: the two blocks that grow with the data (the greeting and the
 * scene-2 headline) are anchored BOTTOM-left, so an extra line grows upward
 * into empty space instead of pushing into the line below it. Nothing in this
 * design depends on a wrap estimate being exactly right.
 */
function buildTemplate(cfg) {
  const paper = clean(cfg.paperColor) || '#F2EFE9';
  const ink = clean(cfg.inkColor) || '#131A22';
  const brand = clean(cfg.brandColor) || '#1B3B5A';
  const accent = clean(cfg.accentColor) || '#A85F22';
  const muted = '#5A6672';
  const paperSoft = '#C3D0DE';
  const display = clean(cfg.displayFont) || 'Fraunces';
  const ui = clean(cfg.uiFont) || 'Archivo';

  const senderName = clean(cfg.senderName) || 'Your name';
  const senderTitle = clean(cfg.senderTitle) || 'Founder';
  const senderCompany = clean(cfg.senderCompany) || 'Your company';
  // A malformed senderLogoUrl silently becomes the sender's monogram rather
  // than a broken <img> in every video of the batch.
  const senderLogoRaw = clean(cfg.senderLogoUrl);
  const senderLogo = LOGO_URL_RE.test(senderLogoRaw) ? senderLogoRaw : '';
  const introLine = clean(cfg.introLine) || 'I put this together just for';
  const kicker = (clean(cfg.pitchKicker) || "Why I'm reaching out").toUpperCase();
  const headPrefix = clean(cfg.pitchHeadline) || "Here's why I thought of";
  const ctaText = clean(cfg.ctaText) || 'Worth fifteen minutes?';
  const meetingLabel = prettyLink(cfg.meetingUrl) || 'yourcalendar.example';

  // 2–3 points; anything past this wraps out of its row.
  const points = (Array.isArray(cfg.pitchPoints) ? cfg.pitchPoints : [])
    .map((p) => clean(p))
    .filter(Boolean)
    .slice(0, 3)
    .map((p) => cap(p, 112));
  if (!points.length) {
    throw new Error(
      'Config.pitchPoints is empty — add two or three short lines about why you are reaching out.'
    );
  }

  const d1 = 3.8; // hello
  const d2 = 5.0; // why
  const d3 = 4.0; // cta
  const t1 = 0.55;
  const t2 = 0.5;

  // ---- sender mark: real logo, or the sender's own monogram ---------------
  const senderInitials =
    senderCompany
      .split(' ')
      .map((w) => (w.match(/[A-Za-z0-9]/) || [''])[0])
      .join('')
      .toUpperCase()
      .slice(0, 2) || 'YC';
  const markInner = (w, h) =>
    senderLogo
      ? "<img src='" + esc(senderLogo) + "' alt='' style='max-width:" + (w - 44) +
        'px; max-height:' + (h - 34) + "px; object-fit:contain;'>"
      : "<div style='width:" + Math.round(h * 0.76) + 'px; height:' + Math.round(h * 0.76) +
        "px; border-radius:999px; background:" + rgba(brand, 0.12) + '; color:' + brand +
        "; display:flex; align-items:center; justify-content:center; font-size:" +
        Math.round(h * 0.34) + "px; font-weight:800; letter-spacing:1px;'>" +
        esc(senderInitials) + '</div>';
  const markBox = (w, h) =>
    "<div style='width:" + w + 'px; height:' + h +
    "px; display:flex; align-items:center; justify-content:center;'>" + markInner(w, h) + '</div>';

  // Tile captions are centred in a 340px column, so the sender's name can wrap
  // to a second line instead of running under its neighbour.
  const senderCaption = cap(senderCompany.toUpperCase(), 34);
  const senderCaptionSize = senderCaption.length <= 19 ? 21 : 19;

  // =====================================================================
  // Scene 1 — the greeting
  // =====================================================================
  const s1Svg =
    "<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'>" +
    "<rect width='1920' height='1080' fill='" + paper + "'/>" +
    // The tint sits ABOVE the tiles (its lowest point is y=380) so no arc edge
    // ever cuts across a logo card.
    "<circle cx='1700' cy='-140' r='520' fill='" + rgba(brand, 0.05) + "'/>" +
    "<rect x='110' y='92' width='14' height='14' fill='" + accent + "'/>" +
    "<path d='M110 150 H1810' stroke='" + rgba(ink, 0.14) + "' stroke-width='1.5'/>" +
    "<path d='M110 942 H1810' stroke='" + rgba(ink, 0.12) + "' stroke-width='1.5'/>" +
    "<rect x='1130' y='400' width='300' height='200' rx='26' fill='#FFFFFF' stroke='" +
    rgba(ink, 0.12) + "' stroke-width='1.5'/>" +
    "<rect x='1490' y='400' width='300' height='200' rx='26' fill='#FFFFFF' stroke='" +
    rgba(ink, 0.12) + "' stroke-width='1.5'/>" +
    "<path d='M1436 500 H1450' stroke='" + rgba(ink, 0.3) + "' stroke-width='2'/>" +
    "<path d='M1470 500 H1484' stroke='" + rgba(ink, 0.3) + "' stroke-width='2'/>" +
    "<circle cx='1460' cy='500' r='5' fill='" + accent + "'/>" +
    '</svg>';

  const scene1 = {
    id: 'hello',
    duration: d1,
    backgroundColor: paper,
    transition: 'fade',
    transitionId: 'why',
    transitionDuration: t1,
    visuals: [
      { type: 'SVG', width: CANVAS_W, height: CANVAS_H, track: 0, enterBegin: 0, exitEnd: d1, svg: s1Svg },
      {
        type: 'TEXT', x: 146, y: 99, anchor: 'center-left', track: 1,
        enterBegin: 0.1, enterEnd: 0.45, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: brand },
        html: "<div style='color:" + brand +
          "; font-size:26px; font-weight:800; letter-spacing:7px;'>" +
          esc(cap(senderCompany.toUpperCase(), 44)) + '</div>',
      },
      {
        // bottom-anchored: a long first name grows UP, never into the subline
        type: 'TEXT', x: 110, y: 470, width: 980, anchor: 'bottom-left', track: 2,
        enterBegin: 0.25, enterEnd: 0.85, enterAnimation: 'smoothup', exitEnd: d1,
        style: { fontFamily: display, color: ink },
        html: "<div style='color:" + ink +
          "; font-size:{{greetSize}}px; line-height:1.06; font-weight:600; letter-spacing:-2px;'>Hi {{firstName}},</div>",
      },
      {
        type: 'TEXT', x: 110, y: 508, width: 940, anchor: 'top-left', track: 3,
        enterBegin: 0.55, enterEnd: 1.05, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: muted },
        html: "<div style='color:" + muted +
          "; font-size:40px; line-height:1.4; font-weight:500;'>" + esc(introLine) +
          ' {{company}}.</div>',
      },
      {
        type: 'TEXT', x: 110, y: 850, width: 980, anchor: 'top-left', track: 4,
        enterBegin: 1.15, enterEnd: 1.6, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: ink },
        html: "<div style='color:" + ink +
          "; font-size:27px; font-weight:700; letter-spacing:3px;'>" + esc(cap(senderName, 48)) +
          "</div><div style='margin-top:8px; color:" + muted +
          "; font-size:24px; font-weight:500; letter-spacing:2px;'>" + esc(cap(senderTitle, 44)) +
          ' · ' + esc(cap(senderCompany, 40)) + '</div>',
      },
      {
        type: 'TEXT', x: 1280, y: 500, width: 240, height: 140, anchor: 'center-center', track: 5,
        enterBegin: 0.35, enterEnd: 0.8, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: brand },
        html: markBox(240, 140),
      },
      {
        type: 'TEXT', condition: '{{showLogo}}',
        x: 1640, y: 500, width: 240, height: 140, anchor: 'center-center', track: 6,
        enterBegin: 0.5, enterEnd: 0.95, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: ink },
        html: "<div style='width:240px; height:140px; display:flex; align-items:center; justify-content:center;'>" +
          "<img src='{{logoUrl}}' alt='' style='max-width:196px; max-height:106px; object-fit:contain;'></div>",
      },
      {
        type: 'TEXT', condition: '{{showMonogram}}',
        x: 1640, y: 500, width: 240, height: 140, anchor: 'center-center', track: 6,
        enterBegin: 0.5, enterEnd: 0.95, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: '{{monoInk}}' },
        html: "<div style='width:240px; height:140px; display:flex; align-items:center; justify-content:center;'>" +
          "<div style='width:112px; height:112px; border-radius:999px; background:{{monoBg}}; color:{{monoInk}}; " +
          "display:flex; align-items:center; justify-content:center; font-size:52px; font-weight:800;'>{{monoLetter}}</div></div>",
      },
      {
        type: 'TEXT', x: 1280, y: 640, width: 340, anchor: 'top-center', track: 7,
        enterBegin: 0.6, enterEnd: 1.05, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: ink },
        html: "<div style='text-align:center; color:" + ink + '; font-size:' + senderCaptionSize +
          "px; line-height:1.35; font-weight:700; letter-spacing:3px;'>" + esc(senderCaption) + '</div>',
      },
      {
        type: 'TEXT', x: 1640, y: 640, width: 340, anchor: 'top-center', track: 8,
        enterBegin: 0.65, enterEnd: 1.1, enterAnimation: 'fade', exitEnd: d1,
        style: { fontFamily: ui, color: ink },
        html: "<div style='text-align:center; color:" + ink +
          "; font-size:{{tileSize}}px; line-height:1.35; font-weight:700; letter-spacing:3px;'>{{companyLabel}}</div>" +
          "<div style='margin-top:6px; text-align:center; color:" + muted +
          "; font-size:19px; font-weight:500; letter-spacing:1px;'>{{websiteLine}}</div>",
      },
    ],
  };

  // =====================================================================
  // Scene 2 — why this lead
  // =====================================================================
  // Row geometry is Config-level (the points are the same for every lead), so
  // it resolves to literals here; only the headline above it moves per lead,
  // and that block is bottom-anchored.
  const rowStep = 150;
  // Fewer than three points slides the whole block down by half a row per
  // missing point, so a two-point list sits centred in the same band instead
  // of leaving a ~260px hole above the footer rule. Three points (the default)
  // keep their original coordinates exactly.
  const rowTop = 520 + Math.round(((3 - points.length) * rowStep) / 2);
  const rows = points.map((text, i) => ({ y: rowTop + i * rowStep, text }));

  const s2Svg =
    "<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'>" +
    "<rect width='1920' height='1080' fill='" + paper + "'/>" +
    "<rect x='110' y='92' width='14' height='14' fill='" + accent + "'/>" +
    "<path d='M110 150 H1810' stroke='" + rgba(ink, 0.14) + "' stroke-width='1.5'/>" +
    rows
      .map(
        (r) =>
          "<path d='M110 " + (r.y - 30) + " H1810' stroke='" + rgba(ink, 0.12) +
          "' stroke-width='1.5'/>"
      )
      .join('') +
    "<path d='M110 986 H1810' stroke='" + rgba(ink, 0.12) + "' stroke-width='1.5'/>" +
    '</svg>';

  const rowVisual = (r, i) => ({
    type: 'TEXT',
    x: 110,
    y: r.y,
    width: 1700,
    anchor: 'top-left',
    track: 4 + i,
    // Staggered in AFTER the incoming headline has settled (see scene 2's
    // headline note) so the list never animates on top of a dissolve.
    enterBegin: 1.05 + i * 0.32,
    enterEnd: 1.5 + i * 0.32,
    enterAnimation: 'smoothleft',
    exitEnd: d2,
    style: { fontFamily: ui, color: ink },
    html:
      "<div style='display:flex; align-items:flex-start;'>" +
      "<div style='width:92px; flex-shrink:0; color:" + accent +
      "; font-size:26px; font-weight:800; letter-spacing:2px; padding-top:10px;'>" +
      ('0' + (i + 1)) +
      "</div><div style='color:" + ink +
      "; font-size:38px; line-height:1.35; font-weight:500;'>" + esc(r.text) + '</div></div>',
  });

  const scene2 = {
    id: 'why',
    duration: d2,
    backgroundColor: paper,
    transition: 'fade',
    transitionId: 'cta',
    transitionDuration: t2,
    visuals: [
      { type: 'SVG', width: CANVAS_W, height: CANVAS_H, track: 0, enterBegin: 0, exitEnd: d2, svg: s2Svg },
      {
        type: 'TEXT', x: 146, y: 99, anchor: 'center-left', track: 1,
        enterBegin: 0.1, enterEnd: 0.45, enterAnimation: 'fade', exitEnd: d2,
        style: { fontFamily: ui, color: brand },
        html: "<div style='color:" + brand +
          "; font-size:26px; font-weight:800; letter-spacing:7px;'>" + esc(cap(kicker, 52)) + '</div>',
      },
      {
        // bottom-anchored: a two-line headline grows up, never onto the role line.
        // enterBegin sits PAST the incoming fade (t1 = 0.55 s): scene 1's subline
        // already names the company, and starting this headline inside the
        // dissolve stacked two dark display-serif blocks on top of each other.
        type: 'TEXT', x: 110, y: 380, width: 1500, anchor: 'bottom-left', track: 2,
        enterBegin: 0.6, enterEnd: 1.15, enterAnimation: 'smoothup', exitEnd: d2,
        style: { fontFamily: display, color: ink },
        html: "<div style='color:" + ink +
          "; font-size:{{headSize}}px; line-height:1.12; font-weight:600; letter-spacing:-1.5px;'>" +
          esc(headPrefix) + ' {{company}}</div>',
      },
      {
        type: 'TEXT', x: 110, y: 412, width: 1500, anchor: 'top-left', track: 3,
        enterBegin: 0.9, enterEnd: 1.4, enterAnimation: 'fade', exitEnd: d2,
        style: { fontFamily: ui, color: muted },
        html: "<div style='color:" + muted +
          "; font-size:33px; line-height:1.35; font-weight:500;'>{{roleLine}}</div>",
      },
      ...rows.map(rowVisual),
      {
        type: 'TEXT', x: 110, y: 1006, width: 1700, anchor: 'top-left', track: 9,
        enterBegin: 2.0, enterEnd: 2.45, enterAnimation: 'fade', exitEnd: d2,
        style: { fontFamily: ui, color: muted },
        html: "<div style='color:" + muted +
          "; font-size:23px; font-weight:600; letter-spacing:4px;'>" +
          esc(cap(senderCompany.toUpperCase(), 40)) + ' · ' + esc(meetingLabel.toUpperCase()) + '</div>',
      },
    ],
  };

  // =====================================================================
  // Scene 3 — the ask
  // =====================================================================
  const ctaSize = fitSize(ctaText, [78, 66, 56, 48], 1400, SERIF_EM, 2);
  const ctaLines = wrapLines(ctaText, ctaSize, 1400, SERIF_EM);
  // A two-line CTA pushes everything under it down, and the sign-off block at
  // y=868 cannot move (the frame border is at 1024) — so the whole stack starts
  // higher instead of letting the meeting pill crowd the sign-off. A one-line
  // CTA keeps its original geometry exactly.
  const ctaTop = ctaLines >= 2 ? 392 : 430;
  const personalY = ctaTop + ctaLines * Math.round(ctaSize * 1.14) + 36;
  const pillY = personalY + 118;

  const s3Svg =
    "<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'>" +
    "<defs><radialGradient id='coGlow' cx='0.5' cy='0.26' r='0.85'>" +
    "<stop offset='0' stop-color='#FFFFFF' stop-opacity='0.12'/>" +
    "<stop offset='1' stop-color='#FFFFFF' stop-opacity='0'/></radialGradient></defs>" +
    "<rect width='1920' height='1080' fill='" + brand + "'/>" +
    "<rect width='1920' height='1080' fill='url(#coGlow)'/>" +
    "<rect x='70' y='56' width='1780' height='968' rx='30' fill='none' stroke='" +
    rgba(paper, 0.2) + "' stroke-width='1.5'/>" +
    "<path d='M150 140 H240' stroke='" + accent + "' stroke-width='4'/>" +
    "<path d='M1680 940 H1770' stroke='" + rgba(paper, 0.35) + "' stroke-width='4'/>" +
    '</svg>';

  const scene3 = {
    id: 'cta',
    duration: d3,
    backgroundColor: brand,
    visuals: [
      { type: 'SVG', width: CANVAS_W, height: CANVAS_H, track: 0, enterBegin: 0, exitEnd: d3, svg: s3Svg },
      {
        // The white card is painted by the element itself (not the SVG) so the
        // API's contrast lint sees the real background behind this mark.
        type: 'TEXT', x: 960, y: 268, width: 260, height: 150, anchor: 'center-center', track: 1,
        enterBegin: 0.15, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: d3,
        style: { fontFamily: ui, color: brand, backgroundColor: '#FFFFFF', borderRadius: '26px' },
        html: markBox(260, 150),
      },
      {
        type: 'TEXT', x: 960, y: ctaTop, width: 1400, anchor: 'top-center', track: 2,
        enterBegin: 0.3, enterEnd: 0.85, enterAnimation: 'smoothup', exitEnd: d3,
        style: { fontFamily: display, color: paper },
        html: "<div style='text-align:center; color:" + paper + '; font-size:' + ctaSize +
          "px; line-height:1.14; font-weight:600; letter-spacing:-1px;'>" + esc(ctaText) + '</div>',
      },
      {
        type: 'TEXT', x: 960, y: personalY, width: 1240, anchor: 'top-center', track: 3,
        enterBegin: 0.6, enterEnd: 1.05, enterAnimation: 'fade', exitEnd: d3,
        style: { fontFamily: ui, color: paperSoft },
        html: "<div style='text-align:center; color:" + paperSoft +
          "; font-size:31px; line-height:1.4; font-weight:500;'>{{ctaPersonal}}</div>",
      },
      {
        type: 'TEXT', x: 960, y: pillY, anchor: 'top-center', track: 4,
        enterBegin: 0.85, enterEnd: 1.3, enterAnimation: 'circleopen', exitEnd: d3,
        style: { fontFamily: ui, color: brand, backgroundColor: paper, borderRadius: '999px' },
        html: "<div style='padding:22px 58px; color:" + brand +
          "; font-size:33px; font-weight:800; letter-spacing:1px;'>" + esc(meetingLabel) + '</div>',
      },
      {
        type: 'TEXT', x: 960, y: 868, width: 1400, anchor: 'top-center', track: 5,
        enterBegin: 1.2, enterEnd: 1.65, enterAnimation: 'fade', exitEnd: d3,
        style: { fontFamily: ui, color: paper },
        html: "<div style='text-align:center; color:" + paper +
          "; font-size:30px; font-weight:700; letter-spacing:2px;'>" + esc(cap(senderName, 48)) +
          "</div><div style='margin-top:10px; text-align:center; color:" + paperSoft +
          "; font-size:24px; font-weight:500; letter-spacing:2px;'>" + esc(cap(senderTitle, 44)) +
          ' · ' + esc(cap(senderCompany, 40)) + '</div>',
      },
    ],
  };

  const music = clean(cfg.musicUrl);
  const payload = {
    name: 'cold-outreach-video',
    // Explicit 16:9 pixels rather than the "full-hd" preset on purpose: every
    // coordinate in this design is authored against 1920x1080, AND the API's
    // layout linter can only check bounds/overlaps when the canvas size is
    // stated (a resolution preset makes it skip those checks entirely).
    width: CANVAS_W,
    height: CANVAS_H,
    frameRate: Number(cfg.frameRate) || 30,
    backgroundColor: paper,
    outputFormat: 'mp4',
    // Defaults keep every placeholder resolvable on its own; the per-lead
    // items below always override all of them.
    variables: {
      firstName: 'there',
      company: 'your company',
      companyLabel: 'YOUR COMPANY',
      websiteLine: '',
      greetSize: 112,
      headSize: 66,
      tileSize: 21,
      roleLine: 'Written for your team.',
      logoUrl: 'https://cdn.zvid.io/assets/logo.svg',
      showLogo: false,
      showMonogram: true,
      monoLetter: 'Y',
      monoBg: MONOGRAMS[0].bg,
      monoInk: MONOGRAMS[0].ink,
      ctaPersonal: 'Pick any slot that works — the link opens my calendar.',
    },
    scenes: [scene1, scene2, scene3],
    // NOTE: no `track` on the audio — the production API rejects
    // audios[].track ("is not allowed"), even though older library JSONs carry it.
    audios: music ? [{ src: music, volume: Number(cfg.musicVolume) || 0.12 }] : [],
  };

  const seconds = Math.round((d1 + d2 + d3 - t1 - t2) * 100) / 100;
  return {
    payload,
    seconds,
    pointCount: points.length,
    sceneSeconds: [d1, d2, d3],
    senderMark: senderLogo ? 'logo' : 'monogram',
  };
}

/** One bulk item's variables. Everything that lands in HTML is escaped HERE. */
function buildItemVariables(cfg, lead, probe) {
  const firstName = cap(lead.firstName, 40);
  const company = cap(lead.company, 64);
  const role = cap(lead.role, 62);
  const site = domainOf(lead.website);

  const greetText = 'Hi ' + (firstName || 'there') + ',';
  const greetSize = fitSize(greetText, [128, 112, 96, 80, 68, 58, 50], 980, SERIF_EM, 1);

  const headText = (clean(cfg.pitchHeadline) || "Here's why I thought of") + ' ' + (company || 'your team');
  const headSize = fitSize(headText, [76, 66, 58, 50, 44], 1500, SERIF_EM, 2);

  const roleLine = role
    ? 'Written with ' + article(role) + ' ' + role + ' in mind.'
    : company
      ? 'Written for the team at ' + company + '.'
      : 'Written for your team.';

  const companyLabel = cap(company || 'Your company', 30).toUpperCase();
  const tileSize = companyLabel.length <= 19 ? 21 : 19;

  const verdict = logoVerdict(lead.logoUrl, probe, cfg.maxLogoBytes);
  const mono = monogramFor(company || firstName || 'Z');

  const ctaPersonal = firstName
    ? firstName + ', pick any slot that works — the link opens my calendar.'
    : 'Pick any slot that works — the link opens my calendar.';

  return {
    variables: {
      firstName: esc(firstName || 'there'),
      company: esc(company || 'your team'),
      companyLabel: esc(companyLabel),
      websiteLine: esc(site),
      greetSize,
      headSize,
      tileSize,
      roleLine: esc(roleLine),
      // Escaped like every other interpolated value: it lands in an <img src>
      // attribute, and "&" in a query string must ride as "&amp;" there.
      logoUrl: verdict.ok ? esc(clean(lead.logoUrl)) : 'https://cdn.zvid.io/assets/logo.svg',
      showLogo: verdict.ok,
      showMonogram: !verdict.ok,
      monoLetter: esc(mono.letter),
      monoBg: mono.bg,
      monoInk: mono.ink,
      ctaPersonal: esc(ctaPersonal),
    },
    logoMode: verdict.ok ? 'logo' : 'monogram',
    logoReason: verdict.reason,
  };
}

/**
 * leads: [{ rowNumber, firstName, company, website, logoUrl, role }]
 * probes: the HEAD responses from "Check lead logos", same order as leads
 *         (an empty array simply means "not probed" — the logo is trusted).
 */
function buildBulkRequest(config, leads, probes) {
  const cfg = config || {};
  if (!Array.isArray(leads) || leads.length === 0) {
    throw new Error('buildBulkRequest needs at least one lead.');
  }
  const usableProbes =
    Array.isArray(probes) && probes.length === leads.length ? probes : null;

  const { payload, seconds, pointCount, sceneSeconds, senderMark } = buildTemplate(cfg);

  const items = [];
  const meta = { leads: [], probesUsed: Boolean(usableProbes) };
  for (let i = 0; i < leads.length; i++) {
    const lead = leads[i];
    const built = buildItemVariables(cfg, lead, usableProbes ? usableProbes[i] : null);
    const nameBase = slugify((lead.company || 'lead') + '-' + (lead.firstName || ''), 'lead');
    items.push({
      variables: built.variables,
      name: (nameBase + '-r' + (lead.rowNumber == null ? i + 1 : lead.rowNumber)).slice(0, 60),
    });
    meta.leads.push({
      index: i,
      rowNumber: lead.rowNumber == null ? null : lead.rowNumber,
      firstName: clean(lead.firstName),
      company: clean(lead.company),
      role: clean(lead.role),
      logoMode: built.logoMode,
      logoReason: built.logoReason,
    });
  }

  meta.videoSeconds = seconds;
  meta.sceneSeconds = sceneSeconds;
  meta.pitchPoints = pointCount;
  meta.senderMark = senderMark;
  meta.musicUrl = clean(cfg.musicUrl) || null;
  meta.monogramLeads = meta.leads.filter((l) => l.logoMode === 'monogram').length;

  return { payload, items, meta };
}

// === n8n glue ==============================================================
const cfg = $('Config').first().json;
const picked = $('Pick batch')
  .all()
  .map((i) => i.json)
  .filter((l) => l && l.found);

// Music guard: unless the HEAD probe positively confirms the bed is reachable
// and inside the plan's audio cap, render WITHOUT music. This is deliberately
// fail-CLOSED — "Check music track" carries onError:continueRegularOutput, so a
// DNS/TLS/connect failure or a 15 s timeout arrives as an item with NO
// statusCode at all, and keeping the URL in that case would hand ffmpeg an
// input it cannot open and fail every video in the batch.
let musicUrl = clean(cfg.musicUrl);
let musicNote = 'configured track';
if (!musicUrl) {
  // Config deliberately cleared: silent videos, nothing went wrong. (The probe
  // node falls back to the API root for its URL, so its answer is meaningless
  // here and must not be reported as a dropped track.)
  musicNote = 'no musicUrl in Config — rendering without music';
} else {
  try {
    const probe = $('Check music track').first().json;
    const status = Number(probe.statusCode);
    const headers = probe.headers || {};
    const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
    if (status === 405 || status === 501) {
      // Plenty of CDNs serve GET happily and refuse HEAD. Not evidence.
      musicNote = 'configured track (host refuses HEAD, kept)';
    } else if (status !== 200) {
      musicUrl = '';
      musicNote =
        'dropped: HEAD ' +
        (Number.isFinite(status) && status
          ? 'returned HTTP ' + status
          : 'got no answer (unreachable, blocked or timed out)');
    } else if (bytes && bytes > Number(cfg.maxMusicBytes || 5242880)) {
      musicUrl = '';
      musicNote = 'dropped: music file is ' + Math.round(bytes / 1024) + ' KB';
    }
  } catch (e) {
    // The probe node itself is missing (edited workflow) — no evidence either
    // way, so do not silently strip a bed the user did configure.
    musicNote = 'not probed';
  }
}

let probes = [];
try {
  probes = $('Check lead logos')
    .all()
    .map((i) => i.json);
} catch (e) {
  probes = [];
}

const built = buildBulkRequest({ ...cfg, musicUrl }, picked, probes);
built.meta.music = musicNote;
built.meta.leftForNextRun = picked.length ? Number(picked[0].leftForNextRun) || 0 : 0;
built.meta.skipped = picked.length && picked[0].skipped ? picked[0].skipped : [];
return [{ json: built }];

// The free validate endpoint runs the exact resolve+validate pipeline every
// bulk item runs (the FIRST lead's variables against the shared template), so
// a failure here is a payload/data bug — surface the field list instead of a
// generic HTTP error. It also returns the per-video credit price (multiply by
// the lead count for the batch total) and the fully RESOLVED first video,
// which is what the dry run saves as a draft.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
const perVideo = Number(body.creditsRequired) || 0;
return [{
  json: {
    ...build,
    creditsPerVideo: perVideo,
    totalCredits: perVideo * build.items.length,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
    // The resolved first lead's project, exactly as the renderer receives it.
    resolvedFirst: body.payload || null,
  },
}];

// Dry run: everything except the paid bulk submission. Read this output, open
// the editor link, then set dryRun to false in Config to send the batch.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the credit quote.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    videosPlanned: d.items.length,
    leads: d.meta.leads.map((l) => 'row ' + l.rowNumber + ': ' + l.firstName + ' at ' + l.company + ' (' + l.logoMode + ')'),
    leadsWithMonogram: d.meta.monogramLeads,
    creditsPerVideo: d.creditsPerVideo,
    totalCredits: d.totalCredits,
    secondsPerVideo: d.meta.videoSeconds,
    music: d.meta.music,
    rowsSkipped: d.meta.skipped,
    leftForNextRun: d.meta.leftForNextRun,
    warnings: d.warnings,
    editorLink,
    draftId,
    nextStep: editorLink
      ? 'Open editorLink to watch the FIRST lead video in the Zvid editor. Happy? Set dryRun to false in Config and run again — nothing is charged until then.'
      : 'Set dryRun to false in Config and run again — nothing is charged until then.',
  },
}];

// HTTP 202 means the batch is queued. Individual leads can still be rejected
// at submit time (per-item validation is best-effort) — map those back to
// sheet rows so the summary can name them. Job names stay NULL until a job
// completes, so results are mapped by jobId -> submit index -> lead, never by
// name.
const res = $input.first().json;
const build = $('Check validation').first().json;

if (!res || !res.bulkId) {
  throw new Error('Bulk submit returned no bulkId: ' + JSON.stringify(res).slice(0, 400));
}

const jobIndexById = {};
for (const j of res.jobs || []) jobIndexById[j.jobId] = j.index;

const rejected = (res.errors || []).map((e) => {
  const l = build.meta.leads[e.item] || {};
  return { rowNumber: l.rowNumber, lead: l.firstName, company: l.company, error: e.error, details: e.details };
});

return [{
  json: {
    bulkId: res.bulkId,
    totalJobs: res.totalJobs,
    creditsReserved: res.creditsReserved,
    queueAhead: res.queueAhead,
    jobIndexById,
    rejected,
  },
}];

// Fails fast when the whole batch failed, and stops the poll loop at
// timeoutMinutes. A timeout does NOT cancel anything — the remaining videos
// finish on Zvid's side (https://app.zvid.io); raise timeoutMinutes for bigger
// lead lists rather than re-running immediately.
const cfg = $('Config').first().json;
const poll = $input.first().json;
const b = poll.bulk || {};
const c = b.counts || {};

if (b.status === 'failed') {
  const firstError = (poll.jobs || []).map((j) => j.errorMessage).filter(Boolean)[0];
  throw new Error('Every video in bulk ' + b.id + ' failed. First error: ' + (firstError || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 30) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(
    'Bulk ' + b.id + ' did not finish within ' + cfg.timeoutMinutes + ' minutes (' +
    (c.completed || 0) + '/' + b.totalJobs + ' done, ' + (c.pending || 0) + ' still rendering). ' +
    'The remaining renders continue on Zvid side — check https://app.zvid.io before re-running, or raise timeoutMinutes.'
  );
}

return $input.all();

// Maps every finished job back to its lead and emits ONE ITEM PER VIDEO,
// shaped for the Google Sheets update node. A lead whose render failed is
// named here and keeps an empty Status/VideoUrl, so the next run picks exactly
// that lead up again (failed renders are refunded automatically).
const poll = $input.first().json;
const sub = $('Check batch accepted').first().json;
const build = $('Check validation').first().json;
const cfg = $('Config').first().json;
const b = poll.bulk || {};

const updates = [];
const failures = [];
for (const job of poll.jobs || []) {
  const index = sub.jobIndexById[job.id];
  const lead = index != null ? build.meta.leads[index] : null;
  if (!lead) continue;
  if (job.status === 'completed' && job.outputUrl) {
    updates.push({
      row_number: lead.rowNumber,
      Status: cfg.statusDoneValue || 'done',
      VideoUrl: job.outputUrl,
      videoUrl: job.outputUrl,
      firstName: lead.firstName,
      company: lead.company,
      role: lead.role,
      logoMode: lead.logoMode,
      jobId: job.id,
      creditsUsed: job.creditsConsumed == null ? null : Number(job.creditsConsumed),
    });
  } else {
    failures.push({
      rowNumber: lead.rowNumber,
      lead: lead.firstName + ' at ' + lead.company,
      status: job.status,
      error: job.errorMessage || null,
    });
  }
}

// Leads the API rejected at submit time never got a job at all.
for (const r of sub.rejected || []) {
  failures.push({ rowNumber: r.rowNumber, lead: r.lead + ' at ' + r.company, status: 'rejected', error: r.error });
}

if (!updates.length) {
  const first = failures[0];
  throw new Error(
    'Bulk ' + b.id + ' finished but produced no videos (' + failures.length + ' failed). First failure: row ' +
    (first ? first.rowNumber + ' — ' + first.lead + ': ' + (first.error || first.status) : 'unknown') +
    '. Those rows keep an empty Status, so the next run retries them.'
  );
}

return updates.map((u) => ({ json: { ...u, failed: failures } }));

// ONE ITEM PER VIDEO: each carries its lead, the video URL and the batch
// totals, so the next node (▶ Watch video) yields one player per lead.
const poll = $('Get batch status').first().json;
const sub = $('Check batch accepted').first().json;
const build = $('Check validation').first().json;
const cfg = $('Config').first().json;
const delivered = $('Collect finished videos').all().map((i) => i.json);
const failures = delivered.length ? delivered[0].failed || [] : [];

// The sheet write is the one step that can do nothing and still look fine: an
// update that matches no row returns zero items, silently. "Write URLs back"
// runs with alwaysOutputData so this node still executes and can say so.
const written = $('Write URLs back').all().map((i) => i.json).filter((w) => w && w.VideoUrl);
const sheetWarning =
  delivered.length && !written.length
    ? 'The videos rendered, but the sheet write matched no rows — open "Write URLs back" and set "Column to match on" back to row_number (n8n re-points it whenever the node is reconfigured). Every URL is in this output, and the rows re-render on the next run.'
    : null;

const creditsSpent = (poll.jobs || []).reduce((s, j) => s + (Number(j.creditsConsumed) || 0), 0);

const batch = {
  bulkId: sub.bulkId,
  bulkStatus: (poll.bulk || {}).status,
  videosDelivered: delivered.length,
  videosFailed: failures.length,
  failed: failures,
  creditsSpent: creditsSpent || sub.creditsReserved,
  creditsPerVideo: build.creditsPerVideo,
  sheetRowsWritten: written.length,
  sheetStatus: cfg.statusDoneValue,
  rowsSkippedBeforeSubmit: build.meta.skipped,
  leadsWithMonogram: build.meta.monogramLeads,
  music: build.meta.music,
  leftForNextRun: build.meta.leftForNextRun,
  sheetWarning,
  note: failures.length
    ? 'Leads that failed keep an empty Status and are picked up again on the next run. Failed renders are refunded automatically.'
    : 'Every lead in this batch now has a video and a filled sheet row.',
};

return delivered.map((d) => ({
  json: {
    lead: d.firstName + ' at ' + d.company,
    firstName: d.firstName,
    company: d.company,
    role: d.role,
    logoMode: d.logoMode,
    sheetRow: d.row_number,
    videoUrl: d.videoUrl,
    jobId: d.jobId,
    creditsUsed: d.creditsUsed,
    videoSeconds: build.meta.videoSeconds,
    batch,
  },
}));
